import{_ as t,C as s,o as n,c as i,a5 as r,E as l}from"./chunks/framework.BwlBv862.js";const v=JSON.parse('{"title":"Installer et gérer les plugins","description":"","frontmatter":{"title":"Installer et gérer les plugins","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"93c8811682d0baa5bd18b571503fce483cf1f464e94b94bc933241bf277d23d4","translationRevision":"f3e1ebd6f94f323f027455d5b184b8f741229606952e105eec476c136a2d5d87","order":10},"headers":[],"relativePath":"fr/user/plugins/index.md","filePath":"fr/user/plugins/index.md","lastUpdated":1794611623000}'),o={name:"fr/user/plugins/index.md"};function u(d,e,c,p,m,f){const a=s("DemoFrame");return n(),i("div",null,[e[0]||(e[0]=r('<h1 id="install-and-manage-plugins" tabindex="-1">Installer et gérer les plugins <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to &quot;Installer et gérer les plugins {#install-and-manage-plugins}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Ajouter une intégration, examiner les accès demandés et confirmer que ses actions sont utilisables. Il faut un paquet de bureau compatible avec le système d’exploitation, l’architecture et la version d’hôte du plugin. Les opérations de catalogue distant et de téléchargement nécessitent un accès réseau ; certains services liés au compte nécessitent aussi une <a href="./../cloud/account.html">connexion Cloud</a>.</p><h2 id="review-before-enabling" tabindex="-1">Examiner avant d’activer <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to &quot;Examiner avant d’activer {#review-before-enabling}&quot;">​</a></h2><ol><li>Ouvrez <strong>Plugins</strong> et examinez Installed, Explore ou Updates. Explore demande uniquement des entrées de plugins. Les modèles et profils d’automatisation se trouvent dans <a href="./../automations/templates.html">Automations</a>.</li><li>Sélectionnez un plugin pour examiner sa description, sa version, sa compatibilité et son environnement d’exécution. Vérifiez l’éditeur et les capacités ou permissions demandées plutôt que de vous fier uniquement à un nom familier.</li><li>Utilisez le parcours d’installation pour examiner l’aperçu du paquet. Examinez la version exacte, les informations de signature, les accès demandés et les différences avec une version installée avant de confirmer l’installation.</li><li>Attendez le résultat de la tâche de paquet. Téléchargement, installation et activation sont des étapes distinctes ; une fiche de catalogue seule ne signifie pas que l’environnement d’exécution est prêt.</li><li>Ouvrez le volet Settings ou Connection du plugin. Fournissez l’adresse de son service et ses identifiants uniquement dans les champs prévus. Utilisez la vérification de connexion déclarée lorsqu’elle est proposée.</li><li>Activez le plugin, puis vérifiez l’apparition de ses types d’action ou pages. Créez une <a href="./../automations/first-rule.html">règle de journalisation</a> ciblée avant d’attacher une action externe puissante.</li></ol><p>Les plugins peuvent exécuter du code natif ou des processus séparés. Une frontière de processus peut isoler un plantage, mais ne constitue pas un bac à sable du système d’exploitation. Installez des logiciels provenant d’éditeurs de confiance. Une signature valide identifie la provenance vérifiée d’un paquet ; elle ne rend pas chaque effet approprié à votre usage.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>L’examen des paquets, les tâches d’installation, les préférences de plugins et la gestion des versions sont disponibles. Les actions réelles dépendent du manifeste installé, des capacités de l’hôte et du service externe. Les processeurs d’événements ont leur propre panneau et peuvent ajouter des champs d’analyse facultatifs aux événements ; les champs bruts restent distincts.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>En cas d’échec d’installation, lisez l’erreur de tâche pour identifier un problème de compatibilité, signature, exécution ou téléchargement. N’affaiblissez pas la vérification simplement pour effacer l’erreur. Si une mise à jour pose problème, examinez les versions conservées et utilisez le retour arrière lorsqu’il est disponible. Examinez les automatisations dépendantes avant de désactiver ou désinstaller un plugin. Gardez des <a href="./../preferences/backups.html">sauvegardes</a> des données et configurations des plugins avant de les supprimer.</p>',10)),l(a,{scenario:"plugins",locale:"fr",tour:"plugin",title:"Démo : plugins"})])}const h=t(o,[["render",u]]);export{v as __pageData,h as default};
